<style>.acceso-global{margin:2px 0 10px}.acceso-global-check{display:flex;gap:10px;align-items:flex-start;padding:10px 12px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--tx);cursor:pointer;font-weight:normal}.acceso-global-check:has(input:checked){border-color:#cc4a05;background:#fff7f1;box-shadow:0 0 0 2px #cc4a0522}.acceso-global-check input{width:auto;min-height:0;margin-top:3px;accent-color:#cc4a05}.acceso-global-check strong,.acceso-global-check small{display:block}.acceso-global-check small{color:var(--muted);font-size:12px}.acceso-global-aviso{margin:0 0 8px;padding:9px 12px;border-radius:9px;background:#fff7f1;border-left:4px solid #cc4a05;color:var(--tx);font-size:13px}#sucursales:disabled{background:#f1f0ed;color:var(--muted);cursor:not-allowed}</style>
<script>const roles=document.getElementById('rol'), branches=document.getElementById('sucursales'), globalBox=document.getElementById('acceso-global-box'), globalCheck=document.getElementById('acceso-global'), globalHidden=document.getElementById('acceso-global-hidden'), globalNotice=document.getElementById('acceso-global-aviso'); function sync(){const option=roles.selectedOptions[0]; const cashier=option?.dataset.cajero==='1'; const admin=option?.dataset.admin==='1'; globalBox.hidden=!admin; globalHidden.disabled=!admin; if(!admin){globalCheck.checked=false} globalCheck.disabled=!admin; const global=admin&&globalCheck.checked; globalNotice.hidden=!global; branches.disabled=global; branches.multiple=!cashier; branches.required=cashier||(admin&&!global); if(cashier&&branches.selectedOptions.length>1)[...branches.options].forEach((o,i)=>o.selected=i===[...branches.options].findIndex(x=>x.selected)); document.getElementById('sucursal-label').textContent=cashier?'Sucursal asignada *':(admin&&!global?'Sucursales autorizadas *':'Sucursales autorizadas')} roles.addEventListener('change',sync); globalCheck.addEventListener('change',sync); sync();</script>
